defmodule Manifests.CatalogTools.Docs do
  @moduledoc """
  The generated documentation: each `MANIFEST.md` body (`render/5`) and `CATALOG.md`
  (`render_catalog/2`), byte-for-byte what `tools/catalog.py docs` wrote.
  """

  alias Manifests.CatalogTools.{Catalog, Json, Py}

  # Kept identical to the Python tool's text so existing generated files stay current.
  @generated "<!-- Generated by tools/catalog.py from manifest.json. Edit the front matter " <>
               "above or manifest.json, then run `python tools/catalog.py docs`. -->"

  def generated_marker, do: @generated

  defp cell(nil), do: cell_text("")
  defp cell(value), do: cell_text(Py.collapse_ws(Py.str(value)))

  defp cell_text(text) do
    text = text |> String.replace("\\", "\\\\") |> String.replace("|", "\\|") |> Py.strip()
    if text == "", do: "—", else: text
  end

  defp code(value) when value in [nil, ""], do: "—"
  defp code(value), do: "`#{Py.str(value)}`"

  defp params(node) do
    names =
      for p <- Json.get(node, "parameters", []) do
        "`#{cell(Json.get(p, "name"))}`#{if Py.truthy?(Json.get(p, "required")), do: "*", else: ""}"
      end

    request = Json.get(node, "request")

    names =
      if Py.truthy?(request) do
        star = if Py.truthy?(Json.get(request, "required")), do: "*", else: ""
        names ++ ["body#{star}: #{cell(Json.get(request, "type"))}"]
      else
        names
      end

    case Enum.join(names, ", ") do
      "" -> "—"
      text -> text
    end
  end

  defp returns(node) do
    ok =
      for r <- Json.get(node, "responses", []),
          String.starts_with?(Json.fetch!(r, "status"), "2"),
          Py.truthy?(Json.get(r, "type")),
          do: Json.get(r, "type")

    if ok == [], do: "—", else: cell(ok |> Enum.uniq() |> Enum.join(", "))
  end

  @doc "The generated body of an application's MANIFEST.md (everything after the front matter)."
  def render(c, app_id, payload, listing, signed) do
    spec = payload |> Json.get("manifest") |> Py.py_or(%{}) |> Json.get("spec") |> Py.py_or(%{})
    base = spec |> Json.get("base") |> Py.py_or(%{})
    prov = payload |> Json.get("provenance") |> Py.py_or(%{})
    setup = payload |> Json.get("setup") |> Py.py_or(%{})
    rights = payload |> Json.get("rights") |> Py.py_or(%{})
    cred = setup |> Json.get("credential") |> Py.py_or(%{})
    probe = setup |> Json.get("probe") |> Py.py_or(%{})
    s = Map.get(signed, app_id)

    current =
      s != nil and Catalog.same_payload?(s, payload) and
        s.catalog == Json.fetch!(listing, "catalog") and
        Json.eq?(
          s.entry,
          Catalog.index_entry(app_id, payload, listing, Json.fetch!(s.entry, "digest"))
        )

    signature =
      if current do
        {_, dir, _} = Catalog.catalog!(s.catalog)

        "`#{Py.str(Json.fetch!(s.entry, "digest"))}` in `#{dir}/`, expires " <>
          Catalog.iso(Json.fetch!(payload, "expires"))
      else
        "Not signed yet: these sources are waiting for the signing job."
      end

    license = prov |> Json.get("license") |> Py.py_or(%{})
    source_rights = rights |> Json.get("source") |> Py.py_or(%{})
    brand = rights |> Json.get("brand") |> Py.py_or(%{})
    credential = Json.get(cred, "type")

    credential =
      if Py.truthy?(Json.get(cred, "header")) do
        prefix = Json.get(cred, "prefix")
        prefix = if Py.truthy?(prefix), do: " " <> Py.repr(prefix), else: ""
        "#{Py.str(credential)} (`#{Py.str(Json.get(cred, "header"))}`#{prefix})"
      else
        credential
      end

    out = [
      @generated,
      "",
      "# #{Py.str(Json.fetch!(listing, "title"))}",
      "",
      "`#{app_id}` · #{Py.str(Json.get(payload, "protocol"))} · version #{code(Json.get(payload, "version"))} · " <>
        "**#{Py.str(Json.fetch!(listing, "catalog"))}** · readiness `#{Py.str(Json.get(payload, "readiness"))}`",
      ""
    ]

    out =
      if Py.truthy?(Json.get(spec, "description")),
        do: out ++ [cell(Json.get(spec, "description")), ""],
        else: out

    categories = Catalog.categories(c)

    category_titles =
      listing
      |> Json.fetch!("categories")
      |> Enum.map(&(categories |> Json.fetch!(&1) |> Json.fetch!("title")))
      |> Enum.join(", ")

    upstream =
      if Py.truthy?(Json.get(prov, "repository")) do
        commit = Json.get(prov, "commit")

        Json.fetch!(prov, "repository") <>
          if(Py.truthy?(commit), do: " @ `#{Py.cp_take(commit, 12)}`", else: "")
      else
        "—"
      end

    rows = [
      {"Categories", category_titles},
      {"Signed bundle", signature},
      {"Endpoint", code(Json.get(base, "endpoint"))},
      {"Credential", Py.py_or(credential, "—")},
      {"Connection test",
       if(Py.truthy?(probe),
         do:
           Py.strip(
             "#{Py.str(Json.get(probe, "method", ""))} #{code(Json.get(probe, "endpoint"))}"
           ),
         else: "—"
       )},
      {"Setup verification", code(Json.get(payload, "setup_verification"))},
      {"Source definition", Py.py_or(Json.get(prov, "url"), "—")},
      {"Upstream", upstream},
      {"Source SHA-256", code(Json.get(prov, "sha256"))},
      {"Source license",
       source_rights |> Json.get("spdx") |> Py.py_or(Json.get(license, "name")) |> Py.py_or("—")},
      {"Fetched", Py.py_or(Json.get(prov, "fetched_at"), "—")}
    ]

    out =
      out ++
        ["| | |", "| --- | --- |"] ++
        Enum.map(rows, fn {k, v} -> "| #{k} | #{cell(v)} |" end) ++ [""]

    copyright = Json.get(source_rights, "copyright_notice")

    out =
      if Py.truthy?(brand) or Py.truthy?(copyright) do
        attribution = Json.get(brand, "attribution")

        out ++
          ["## Rights", ""] ++
          if(Py.truthy?(attribution), do: [cell(attribution), ""], else: []) ++
          if(Py.truthy?(copyright), do: ["Copyright: #{cell(copyright)}", ""], else: [])
      else
        out
      end

    review = payload |> Json.get("review_required") |> Py.py_or(%{})

    out =
      if Py.truthy?(review) do
        lines =
          for {k, v} <- Enum.sort_by(Json.items(review), &elem(&1, 0)),
              is_boolean(v) or Py.truthy?(v) do
            label = String.replace(k, "_", " ")

            if is_boolean(v),
              do: "- [#{if v, do: " ", else: "x"}] #{label}",
              else: "- [ ] #{label}: #{v |> py_iter() |> Enum.map_join(", ", &Py.str/1)}"
          end

        out ++ ["## Review checklist", ""] ++ lines ++ [""]
      else
        out
      end

    nodes = payload |> Json.get("graph") |> Py.py_or(%{}) |> Json.get("nodes") |> Py.py_or([])
    ops = Enum.filter(nodes, &(Json.get(&1, "kind") == "operation"))

    others =
      nodes
      |> Enum.map(&Json.get(&1, "kind"))
      |> Enum.reject(&(&1 in ["operation", "application"]))
      |> Enum.frequencies()

    out = out ++ ["## Operations (#{length(ops)})", ""]

    out =
      if map_size(others) > 0 do
        summary =
          others
          |> Enum.sort_by(&elem(&1, 0))
          |> Enum.map_join(", ", fn {k, v} -> "#{v} #{Py.str(k)} nodes" end)

        out ++ [summary <> " in the graph.", ""]
      else
        out
      end

    out =
      cond do
        ops == [] ->
          out

        Enum.all?(ops, &(Json.has?(&1, "method") and Json.has?(&1, "path"))) ->
          out ++
            [
              "Parameters marked * are required. Safe operations only read, so a preview may call them.",
              "",
              "| Method | Path | Name | Parameters | Returns | Safe | Summary |",
              "| --- | --- | --- | --- | --- | --- | --- |"
            ] ++
            Enum.map(ops, fn n ->
              "| #{String.upcase(Json.fetch!(n, "method"))} | `#{cell(Json.fetch!(n, "path"))}` | " <>
                "#{cell(Json.get(n, "name"))} | #{params(n)} | #{returns(n)} | " <>
                "#{if Py.truthy?(Json.get(n, "safe")), do: "yes", else: ""} | #{cell(Json.get(n, "summary"))} |"
            end) ++ [""]

        true ->
          out ++
            ["| Operation | Name | Summary |", "| --- | --- | --- |"] ++
            Enum.map(ops, fn n ->
              "| `#{cell(Json.fetch!(n, "id"))}` | #{cell(Json.get(n, "name"))} | #{cell(Json.get(n, "summary"))} |"
            end) ++ [""]
      end

    Enum.join(out, "\n")
  end

  # What iterating a value yields in Python: list items, str characters, dict keys.
  defp py_iter(l) when is_list(l), do: l
  defp py_iter(s) when is_binary(s), do: String.codepoints(s)
  defp py_iter(obj), do: Json.keys(obj)

  @doc "CATALOG.md."
  def render_catalog(c, signed) do
    known = Catalog.categories(c)

    {rows, by_category} =
      c
      |> Catalog.app_ids()
      |> Catalog.pmap(fn app_id ->
        {payload, listing, _} = Catalog.load_app(c, app_id)
        pending = Catalog.pending(app_id, payload, listing, signed, 0, 0)

        ops =
          payload
          |> Json.get("graph")
          |> Py.py_or(%{})
          |> Json.get("nodes", [])
          |> Enum.count(&(Json.get(&1, "kind") == "operation"))

        # Only what the table needs, so the documents can be freed.
        payload =
          for k <- ~w(protocol version readiness),
              Json.has?(payload, k),
              into: %{},
              do: {k, Json.get(payload, k)}

        {app_id, payload, listing, pending, ops}
      end)
      |> Enum.reduce(
        {%{"published" => [], "drafts" => []},
         Map.new(Json.keys(known), &{&1, %{"published" => 0, "drafts" => 0}})},
        fn {app_id, payload, listing, pending, ops}, {rows, by_category} ->
          status = if pending == [], do: "signed", else: "pending"
          categories = Json.fetch!(listing, "categories")
          catalog = Json.fetch!(listing, "catalog")

          by_category =
            Enum.reduce(categories, by_category, fn cat, acc ->
              counts = Map.fetch!(acc, cat)
              Map.put(acc, cat, Map.put(counts, catalog, Map.fetch!(counts, catalog) + 1))
            end)

          row =
            "| [#{cell(Json.fetch!(listing, "title"))}](apps/#{app_id}/MANIFEST.md) | `#{app_id}` | " <>
              "#{Enum.join(categories, ", ")} | #{Py.str(Json.fetch!(payload, "protocol"))} | " <>
              "#{cell(Json.fetch!(payload, "version"))} | #{ops} | `#{Py.str(Json.get(payload, "readiness"))}` | #{status} |"

          {Map.update!(rows, catalog, &[row | &1]), by_category}
        end
      )

    published = Enum.reverse(rows["published"])
    drafts = Enum.reverse(rows["drafts"])

    head = [
      "| Application | Id | Categories | Protocol | Version | Operations | Readiness | Signature |",
      "| --- | --- | --- | --- | --- | --- | --- | --- |"
    ]

    category_rows =
      for {cat, info} <- Json.items(known) do
        n = Map.fetch!(by_category, cat)
        "| `#{cat}` | #{cell(Json.fetch!(info, "title"))} | #{n["published"]} | #{n["drafts"]} |"
      end

    out =
      [
        "<!-- Generated by tools/catalog.py docs. -->",
        "",
        "# Catalog",
        "",
        "#{length(published) + length(drafts)} applications: #{length(published)} published and " <>
          "#{length(drafts)} drafts. Drafts can be browsed but not connected until reviewed and published.",
        "",
        "## Categories",
        "",
        "An application can have up to four categories. They are defined in [categories.json](categories.json).",
        "",
        "| Id | Category | Published | Drafts |",
        "| --- | --- | --- | --- |"
      ] ++
        category_rows ++
        ["", "## Published (#{length(published)})", ""] ++
        head ++
        published ++
        ["", "## Drafts (#{length(drafts)})", ""] ++
        head ++ drafts ++ [""]

    Enum.join(out, "\n")
  end

  @doc "Rewrite every MANIFEST.md body and CATALOG.md."
  def regenerate(c, signed) do
    c
    |> Catalog.app_ids()
    |> Catalog.pmap(fn app_id ->
      {payload, listing, _} = Catalog.load_app(c, app_id)

      Catalog.write!(
        Path.join([Catalog.apps_dir(c), app_id, "MANIFEST.md"]),
        Catalog.front_matter(listing) <> render(c, app_id, payload, listing, signed)
      )
    end)

    Catalog.write!(Catalog.path(c, "CATALOG.md"), render_catalog(c, signed))
  end
end
